insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900073', '$-12$', 'Em uma matriz triangular, somente o produto associado à diagonal principal contribui para o determinante. Multiplicando os três elementos diagonais obtemos o valor pedido. Logo o determinante vale $-12$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000731', '40000000-0000-4000-8000-000000900073', 'Reconheça a forma', 'A matriz é triangular superior.', 1), ('70000000-0000-4000-8000-000009000732', '40000000-0000-4000-8000-000000900073', 'Use a regra', 'O determinante é o produto da diagonal.', 2), ('70000000-0000-4000-8000-000009000733', '40000000-0000-4000-8000-000000900073', 'Multiplique', '$2\cdot(-3)\cdot2=-12$.', 3), ('70000000-0000-4000-8000-000009000734', '40000000-0000-4000-8000-000000900073', 'Conclua', 'Logo o determinante vale $-12$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900074', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090005', 'multiple_choice', 'easy', 'published', 'Uma matriz $B$ é obtida de $A$ trocando duas linhas, e $\det A=7$. Quanto vale $\det B$?')
