insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000741', '40000000-0000-4000-8000-000000900074', 'Identifique a propriedade estrutural relevante antes de calcular.', 1), ('60000000-0000-4000-8000-000009000742', '40000000-0000-4000-8000-000000900074', 'Faça o cálculo simbólico de forma organizada.', 2), ('60000000-0000-4000-8000-000009000743', '40000000-0000-4000-8000-000000900074', 'Confira o resultado por traço, determinante, dimensão ou substituição.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900074', '$-7$', 'Uma única troca de duas linhas inverte o sinal do determinante, sem alterar seu módulo. Portanto o valor sete passa imediatamente a menos sete. O valor é $-7$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000741', '40000000-0000-4000-8000-000000900074', 'Identifique a operação', 'Houve uma troca de linhas.', 1), ('70000000-0000-4000-8000-000009000742', '40000000-0000-4000-8000-000000900074', 'Use o efeito', 'Cada troca multiplica o determinante por $-1$.', 2), ('70000000-0000-4000-8000-000009000743', '40000000-0000-4000-8000-000000900074', 'Calcule', '$\det B=-\det A=-7$.', 3), ('70000000-0000-4000-8000-000009000744', '40000000-0000-4000-8000-000000900074', 'Conclua', 'O valor é $-7$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900075', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090005', 'multiple_choice', 'easy', 'published', 'Os vetores $(3,0)$ e $(1,4)$ formam lados de um paralelogramo. Qual é sua área?')
