insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000751', '40000000-0000-4000-8000-000000900075', 'Identifique a propriedade estrutural relevante antes de calcular.', 1), ('60000000-0000-4000-8000-000009000752', '40000000-0000-4000-8000-000000900075', 'Faça o cálculo simbólico de forma organizada.', 2), ('60000000-0000-4000-8000-000009000753', '40000000-0000-4000-8000-000000900075', 'Confira o resultado por traço, determinante, dimensão ou substituição.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900075', '$12$', 'A área do paralelogramo é o valor absoluto do determinante formado pelos vetores. O determinante é doze e já é positivo. A área é $12$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000751', '40000000-0000-4000-8000-000000900075', 'Monte a matriz', '$\begin{pmatrix}3&1\\0&4\end{pmatrix}$.', 1), ('70000000-0000-4000-8000-000009000752', '40000000-0000-4000-8000-000000900075', 'Calcule o determinante', '$3\cdot4-0\cdot1=12$.', 2), ('70000000-0000-4000-8000-000009000753', '40000000-0000-4000-8000-000000900075', 'Tome o módulo', '$|12|=12$.', 3), ('70000000-0000-4000-8000-000009000754', '40000000-0000-4000-8000-000000900075', 'Interprete', 'A área é $12$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900076', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090005', 'multiple_choice', 'easy', 'published', 'Para $A=\begin{pmatrix}2&1\\0&3\end{pmatrix}$, qual vetor é autovetor associado a $\lambda=2$?')
