insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000761', '40000000-0000-4000-8000-000000900076', 'Identifique a propriedade estrutural relevante antes de calcular.', 1), ('60000000-0000-4000-8000-000009000762', '40000000-0000-4000-8000-000000900076', 'Faça o cálculo simbólico de forma organizada.', 2), ('60000000-0000-4000-8000-000009000763', '40000000-0000-4000-8000-000000900076', 'Confira o resultado por traço, determinante, dimensão ou substituição.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900076', '$(1,0)$', 'Um autovetor para o valor dois deve ser não nulo e satisfazer $Av=2v$. A primeira direção coordenada cumpre exatamente essa igualdade. Ele é autovetor de autovalor $2$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000761', '40000000-0000-4000-8000-000000900076', 'Teste a condição', '$A(1,0)=(2,0)$.', 1), ('70000000-0000-4000-8000-000009000762', '40000000-0000-4000-8000-000000900076', 'Compare', '$2(1,0)=(2,0)$.', 2), ('70000000-0000-4000-8000-000009000763', '40000000-0000-4000-8000-000000900076', 'Verifique não nulidade', '$(1,0)$ não é nulo.', 3), ('70000000-0000-4000-8000-000009000764', '40000000-0000-4000-8000-000000900076', 'Conclua', 'Ele é autovetor de autovalor $2$.', 4)
