insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000771', '40000000-0000-4000-8000-000000900077', 'Identifique a propriedade estrutural relevante antes de calcular.', 1), ('60000000-0000-4000-8000-000009000772', '40000000-0000-4000-8000-000000900077', 'Faça o cálculo simbólico de forma organizada.', 2), ('60000000-0000-4000-8000-000009000773', '40000000-0000-4000-8000-000000900077', 'Confira o resultado por traço, determinante, dimensão ou substituição.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900077', '$5,-1,2$', 'Em uma matriz diagonal, cada vetor da base padrão é escalado pelo elemento diagonal correspondente. Assim os próprios elementos da diagonal são os autovalores. Os autovalores são $5,-1,2$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000771', '40000000-0000-4000-8000-000000900077', 'Observe a forma', '$D$ é diagonal.', 1), ('70000000-0000-4000-8000-000009000772', '40000000-0000-4000-8000-000000900077', 'Aplique em $e_1$', '$De_1=5e_1$.', 2), ('70000000-0000-4000-8000-000009000773', '40000000-0000-4000-8000-000000900077', 'Repita', '$De_2=-e_2$ e $De_3=2e_3$.', 3), ('70000000-0000-4000-8000-000009000774', '40000000-0000-4000-8000-000000900077', 'Liste', 'Os autovalores são $5,-1,2$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900078', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090005', 'multiple_choice', 'easy', 'published', 'Uma matriz $2\times2$ tem autovalores $3$ e $-2$. Quais são seu traço e seu determinante?')
