insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900078', '$1$ e $-6$', 'O traço é a soma dos autovalores com multiplicidade, enquanto o determinante é seu produto. Isso fornece um e menos seis, respectivamente. Traço $1$ e determinante $-6$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000781', '40000000-0000-4000-8000-000000900078', 'Some os autovalores', '$3+(-2)=1$.', 1), ('70000000-0000-4000-8000-000009000782', '40000000-0000-4000-8000-000000900078', 'Multiplique', '$3\cdot(-2)=-6$.', 2), ('70000000-0000-4000-8000-000009000783', '40000000-0000-4000-8000-000000900078', 'Associe', 'Soma corresponde ao traço.', 3), ('70000000-0000-4000-8000-000009000784', '40000000-0000-4000-8000-000000900078', 'Conclua', 'Traço $1$ e determinante $-6$.', 4)
