insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000791', '40000000-0000-4000-8000-000000900079', 'Identifique a propriedade estrutural relevante antes de calcular.', 1), ('60000000-0000-4000-8000-000009000792', '40000000-0000-4000-8000-000000900079', 'Faça o cálculo simbólico de forma organizada.', 2), ('60000000-0000-4000-8000-000009000793', '40000000-0000-4000-8000-000000900079', 'Confira o resultado por traço, determinante, dimensão ou substituição.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900079', '$12$', 'Escalar uma linha por três escala o determinante pelo mesmo fator. Somar um múltiplo de uma linha a outra não o altera, então o resultado é doze. O novo determinante é $12$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000791', '40000000-0000-4000-8000-000000900079', 'Acompanhe a escala', 'A primeira operação multiplica o determinante por $3$.', 1), ('70000000-0000-4000-8000-000009000792', '40000000-0000-4000-8000-000000900079', 'Calcule o parcial', '$3\cdot4=12$.', 2), ('70000000-0000-4000-8000-000009000793', '40000000-0000-4000-8000-000000900079', 'Analise a soma de linhas', 'Ela preserva o determinante.', 3), ('70000000-0000-4000-8000-000009000794', '40000000-0000-4000-8000-000000900079', 'Conclua', 'O novo determinante é $12$.', 4)
