insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000801', '40000000-0000-4000-8000-000000900080', 'Identifique a propriedade estrutural relevante antes de calcular.', 1), ('60000000-0000-4000-8000-000009000802', '40000000-0000-4000-8000-000000900080', 'Faça o cálculo simbólico de forma organizada.', 2), ('60000000-0000-4000-8000-000009000803', '40000000-0000-4000-8000-000000900080', 'Confira o resultado por traço, determinante, dimensão ou substituição.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900080', '$t=\pm\sqrt6$', 'Uma matriz quadrada é singular exatamente quando seu determinante é zero. A equação resultante é $t^2-6=0$, com duas raízes reais. $t=\pm\sqrt6$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000801', '40000000-0000-4000-8000-000000900080', 'Calcule o determinante', '$t^2-2\cdot3=t^2-6$.', 1), ('70000000-0000-4000-8000-000009000802', '40000000-0000-4000-8000-000000900080', 'Imponha singularidade', '$t^2-6=0$.', 2), ('70000000-0000-4000-8000-000009000803', '40000000-0000-4000-8000-000000900080', 'Resolva', '$t^2=6$.', 3), ('70000000-0000-4000-8000-000009000804', '40000000-0000-4000-8000-000000900080', 'Conclua', '$t=\pm\sqrt6$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900081', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090005', 'multiple_choice', 'medium', 'published', 'Qual é o polinômio característico $p(\lambda)=\det(\lambda I-A)$ de $A=\begin{pmatrix}1&2\\0&4\end{pmatrix}$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000811', '40000000-0000-4000-8000-000000900081', 'A', '$(\lambda-1)(\lambda-4)$', 1), ('50000000-0000-4000-8000-000009000812', '40000000-0000-4000-8000-000000900081', 'B', '$(\lambda+1)(\lambda+4)$', 2), ('50000000-0000-4000-8000-000009000813', '40000000-0000-4000-8000-000000900081', 'C', '$\lambda^2-5$', 3), ('50000000-0000-4000-8000-000009000814', '40000000-0000-4000-8000-000000900081', 'D', '$(\lambda-2)(\lambda-3)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900081', '50000000-0000-4000-8000-000009000811') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900081', '30000000-0000-4000-8000-000000000010', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000811', '40000000-0000-4000-8000-000000900081', 'Identifique a propriedade estrutural relevante antes de calcular.', 1), ('60000000-0000-4000-8000-000009000812', '40000000-0000-4000-8000-000000900081', 'Faça o cálculo simbólico de forma organizada.', 2), ('60000000-0000-4000-8000-000009000813', '40000000-0000-4000-8000-000000900081', 'Confira o resultado por traço, determinante, dimensão ou substituição.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900081', '$(\lambda-1)(\lambda-4)$', 'A matriz é triangular, por isso o determinante de $\lambda I-A$ é o produto de seus elementos diagonais. O termo fora da diagonal não altera as raízes. Esse é o polinômio característico.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000811', '40000000-0000-4000-8000-000000900081', 'Forme a matriz', '$\lambda I-A=\begin{pmatrix}\lambda-1&-2\\0&\lambda-4\end{pmatrix}$.', 1), ('70000000-0000-4000-8000-000009000812', '40000000-0000-4000-8000-000000900081', 'Use triangularidade', 'O determinante é o produto diagonal.', 2), ('70000000-0000-4000-8000-000009000813', '40000000-0000-4000-8000-000000900081', 'Multiplique', '$(\lambda-1)(\lambda-4)$.', 3), ('70000000-0000-4000-8000-000009000814', '40000000-0000-4000-8000-000000900081', 'Conclua', 'Esse é o polinômio característico.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900082', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090005', 'multiple_choice', 'medium', 'published', 'Qual é o autoespaço de $A=\begin{pmatrix}3&1\\0&3\end{pmatrix}$ associado a $\lambda=3$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000821', '40000000-0000-4000-8000-000000900082', 'A', '$\{0\}$', 1), ('50000000-0000-4000-8000-000009000822', '40000000-0000-4000-8000-000000900082', 'B', '$\operatorname{span}\{(1,0)\}$', 2), ('50000000-0000-4000-8000-000009000823', '40000000-0000-4000-8000-000000900082', 'C', '$\operatorname{span}\{(0,1)\}$', 3), ('50000000-0000-4000-8000-000009000824', '40000000-0000-4000-8000-000000900082', 'D', '$\mathbb R^2$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900082', '50000000-0000-4000-8000-000009000822') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900082', '30000000-0000-4000-8000-000000000010', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000821', '40000000-0000-4000-8000-000000900082', 'Identifique a propriedade estrutural relevante antes de calcular.', 1), ('60000000-0000-4000-8000-000009000822', '40000000-0000-4000-8000-000000900082', 'Faça o cálculo simbólico de forma organizada.', 2), ('60000000-0000-4000-8000-000009000823', '40000000-0000-4000-8000-000000900082', 'Confira o resultado por traço, determinante, dimensão ou substituição.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900082', '$\operatorname{span}\{(1,0)\}$', 'O autoespaço é o núcleo de $A-3I$. A equação restante força a segunda coordenada a zero e deixa a primeira livre. $E_3=\operatorname{span}\{(1,0)\}$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000821', '40000000-0000-4000-8000-000000900082', 'Subtraia $3I$', '$A-3I=\begin{pmatrix}0&1\\0&0\end{pmatrix}$.', 1), ('70000000-0000-4000-8000-000009000822', '40000000-0000-4000-8000-000000900082', 'Resolva o núcleo', '$y=0$.', 2), ('70000000-0000-4000-8000-000009000823', '40000000-0000-4000-8000-000000900082', 'Parametrize', '$(x,y)=x(1,0)$.', 3), ('70000000-0000-4000-8000-000009000824', '40000000-0000-4000-8000-000000900082', 'Conclua', '$E_3=\operatorname{span}\{(1,0)\}$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900083', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090005', 'multiple_choice', 'medium', 'published', 'Uma matriz real $4\times4$ possui quatro autovalores reais distintos. Qual conclusão é garantida?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000831', '40000000-0000-4000-8000-000000900083', 'A', 'Ela é simétrica.', 1), ('50000000-0000-4000-8000-000009000832', '40000000-0000-4000-8000-000000900083', 'B', 'Seu determinante é positivo.', 2), ('50000000-0000-4000-8000-000009000833', '40000000-0000-4000-8000-000000900083', 'C', 'Ela é diagonalizável sobre $\mathbb R$.', 3), ('50000000-0000-4000-8000-000009000834', '40000000-0000-4000-8000-000000900083', 'D', 'Ela é ortogonal.', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900083', '50000000-0000-4000-8000-000009000833') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900083', '30000000-0000-4000-8000-000000090018', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000831', '40000000-0000-4000-8000-000000900083', 'Identifique a propriedade estrutural relevante antes de calcular.', 1), ('60000000-0000-4000-8000-000009000832', '40000000-0000-4000-8000-000000900083', 'Faça o cálculo simbólico de forma organizada.', 2), ('60000000-0000-4000-8000-000009000833', '40000000-0000-4000-8000-000000900083', 'Confira o resultado por traço, determinante, dimensão ou substituição.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900083', 'Ela é diagonalizável sobre $\mathbb R$.', 'Autovetores associados a autovalores distintos são linearmente independentes. Quatro deles formam uma base de $\mathbb R^4$, o que garante diagonalização. Eles formam uma base de diagonalização.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000831', '40000000-0000-4000-8000-000000900083', 'Associe autovetores', 'Cada autovalor possui um autovetor não nulo.', 1), ('70000000-0000-4000-8000-000009000832', '40000000-0000-4000-8000-000000900083', 'Use independência', 'Autovalores distintos fornecem autovetores independentes.', 2), ('70000000-0000-4000-8000-000009000833', '40000000-0000-4000-8000-000000900083', 'Conte dimensões', 'Há quatro vetores independentes em dimensão quatro.', 3), ('70000000-0000-4000-8000-000009000834', '40000000-0000-4000-8000-000000900083', 'Conclua', 'Eles formam uma base de diagonalização.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900084', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090005', 'multiple_choice', 'medium', 'published', 'Se $A$ satisfaz o polinômio característico $p(\lambda)=\lambda^2-5\lambda+6$, qual identidade permite reduzir $A^2$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000841', '40000000-0000-4000-8000-000000900084', 'A', '$A^2=5A+6I$', 1), ('50000000-0000-4000-8000-000009000842', '40000000-0000-4000-8000-000000900084', 'B', '$A^2=-5A+6I$', 2), ('50000000-0000-4000-8000-000009000843', '40000000-0000-4000-8000-000000900084', 'C', '$A^2=6A-5I$', 3), ('50000000-0000-4000-8000-000009000844', '40000000-0000-4000-8000-000000900084', 'D', '$A^2=5A-6I$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900084', '50000000-0000-4000-8000-000009000844') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900084', '30000000-0000-4000-8000-000000090018', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000841', '40000000-0000-4000-8000-000000900084', 'Identifique a propriedade estrutural relevante antes de calcular.', 1), ('60000000-0000-4000-8000-000009000842', '40000000-0000-4000-8000-000000900084', 'Faça o cálculo simbólico de forma organizada.', 2), ('60000000-0000-4000-8000-000009000843', '40000000-0000-4000-8000-000000900084', 'Confira o resultado por traço, determinante, dimensão ou substituição.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900084', '$A^2=5A-6I$', 'Pelo teorema de Cayley–Hamilton, a matriz anula seu polinômio característico. Isolar o termo quadrático produz a identidade indicada. Essa relação reduz potências superiores.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000841', '40000000-0000-4000-8000-000000900084', 'Aplique o teorema', '$p(A)=0$.', 1), ('70000000-0000-4000-8000-000009000842', '40000000-0000-4000-8000-000000900084', 'Substitua', '$A^2-5A+6I=0$.', 2), ('70000000-0000-4000-8000-000009000843', '40000000-0000-4000-8000-000000900084', 'Isole', '$A^2=5A-6I$.', 3), ('70000000-0000-4000-8000-000009000844', '40000000-0000-4000-8000-000000900084', 'Conclua', 'Essa relação reduz potências superiores.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900085', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090005', 'multiple_choice', 'hard', 'published', 'Se as colunas de $A$ são $u,v,w$ e $\det[u,v,w]=5$, quanto vale $\det[u+2v,v,w]$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000851', '40000000-0000-4000-8000-000000900085', 'A', '$5$', 1), ('50000000-0000-4000-8000-000009000852', '40000000-0000-4000-8000-000000900085', 'B', '$10$', 2), ('50000000-0000-4000-8000-000009000853', '40000000-0000-4000-8000-000000900085', 'C', '$15$', 3), ('50000000-0000-4000-8000-000009000854', '40000000-0000-4000-8000-000000900085', 'D', '$0$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900085', '50000000-0000-4000-8000-000009000851') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900085', '30000000-0000-4000-8000-000000000008', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000851', '40000000-0000-4000-8000-000000900085', 'Identifique a propriedade estrutural relevante antes de calcular.', 1), ('60000000-0000-4000-8000-000009000852', '40000000-0000-4000-8000-000000900085', 'Faça o cálculo simbólico de forma organizada.', 2), ('60000000-0000-4000-8000-000009000853', '40000000-0000-4000-8000-000000900085', 'Confira o resultado por traço, determinante, dimensão ou substituição.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900085', '$5$', 'A linearidade na primeira coluna separa o determinante em dois termos. O termo que repete a coluna $v$ é zero por alternância, restando o valor original. O determinante permanece $5$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000851', '40000000-0000-4000-8000-000000900085', 'Expanda a coluna', '$\det[u+2v,v,w]=\det[u,v,w]+2\det[v,v,w]$.', 1), ('70000000-0000-4000-8000-000009000852', '40000000-0000-4000-8000-000000900085', 'Use alternância', '$\det[v,v,w]=0$.', 2), ('70000000-0000-4000-8000-000009000853', '40000000-0000-4000-8000-000000900085', 'Substitua', '$5+2\cdot0=5$.', 3), ('70000000-0000-4000-8000-000009000854', '40000000-0000-4000-8000-000000900085', 'Conclua', 'O determinante permanece $5$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900086', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090005', 'multiple_choice', 'hard', 'published', 'Uma matriz $3\times3$ tem polinômio característico $(\lambda-2)^3$ e $\dim\ker(A-2I)=2$. O que se conclui?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000861', '40000000-0000-4000-8000-000000900086', 'A', 'Tem três autovalores distintos.', 1), ('50000000-0000-4000-8000-000009000862', '40000000-0000-4000-8000-000000900086', 'B', 'Não é diagonalizável.', 2), ('50000000-0000-4000-8000-000009000863', '40000000-0000-4000-8000-000000900086', 'C', 'É diagonalizável.', 3), ('50000000-0000-4000-8000-000009000864', '40000000-0000-4000-8000-000000900086', 'D', 'É necessariamente simétrica.', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900086', '50000000-0000-4000-8000-000009000862') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900086', '30000000-0000-4000-8000-000000000010', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000861', '40000000-0000-4000-8000-000000900086', 'Identifique a propriedade estrutural relevante antes de calcular.', 1), ('60000000-0000-4000-8000-000009000862', '40000000-0000-4000-8000-000000900086', 'Faça o cálculo simbólico de forma organizada.', 2), ('60000000-0000-4000-8000-000009000863', '40000000-0000-4000-8000-000000900086', 'Confira o resultado por traço, determinante, dimensão ou substituição.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900086', 'Não é diagonalizável.', 'A multiplicidade algébrica de dois é três, mas o autoespaço tem somente dimensão dois. Faltam autovetores para formar uma base completa. Não existem três autovetores independentes.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000861', '40000000-0000-4000-8000-000000900086', 'Leia a multiplicidade algébrica', 'O autovalor $2$ aparece três vezes.', 1), ('70000000-0000-4000-8000-000009000862', '40000000-0000-4000-8000-000000900086', 'Leia a geométrica', 'O autoespaço tem dimensão $2$.', 2), ('70000000-0000-4000-8000-000009000863', '40000000-0000-4000-8000-000000900086', 'Compare', 'A multiplicidade geométrica é menor que a algébrica.', 3), ('70000000-0000-4000-8000-000009000864', '40000000-0000-4000-8000-000000900086', 'Conclua', 'Não existem três autovetores independentes.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900087', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090005', 'multiple_choice', 'hard', 'published', 'Se $Av_1=4v_1$, $Av_2=-v_2$ e $(v_1,v_2)$ é uma base, qual fatoração diagonaliza $A$ para $P=(v_1\ v_2)$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000871', '40000000-0000-4000-8000-000000900087', 'A', '$A=P\operatorname{diag}(-1,4)P^{-1}$', 1), ('50000000-0000-4000-8000-000009000872', '40000000-0000-4000-8000-000000900087', 'B', '$A=P^{-1}P$', 2), ('50000000-0000-4000-8000-000009000873', '40000000-0000-4000-8000-000000900087', 'C', '$A=P\operatorname{diag}(4,-1)P^{-1}$', 3), ('50000000-0000-4000-8000-000009000874', '40000000-0000-4000-8000-000000900087', 'D', '$A=P^{-1}\operatorname{diag}(4,-1)P$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900087', '50000000-0000-4000-8000-000009000873') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900087', '30000000-0000-4000-8000-000000090018', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000871', '40000000-0000-4000-8000-000000900087', 'Identifique a propriedade estrutural relevante antes de calcular.', 1), ('60000000-0000-4000-8000-000009000872', '40000000-0000-4000-8000-000000900087', 'Faça o cálculo simbólico de forma organizada.', 2), ('60000000-0000-4000-8000-000009000873', '40000000-0000-4000-8000-000000900087', 'Confira o resultado por traço, determinante, dimensão ou substituição.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900087', '$A=P\operatorname{diag}(4,-1)P^{-1}$', 'As colunas de $P$ são autovetores na mesma ordem em que seus autovalores aparecem na diagonal. A relação $AP=PD$ equivale à fatoração dada. A ordem das colunas determina a ordem diagonal.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000871', '40000000-0000-4000-8000-000000900087', 'Agrupe as equações', '$AP=(Av_1\ Av_2)$.', 1), ('70000000-0000-4000-8000-000009000872', '40000000-0000-4000-8000-000000900087', 'Use os autovalores', '$AP=P\operatorname{diag}(4,-1)$.', 2), ('70000000-0000-4000-8000-000009000873', '40000000-0000-4000-8000-000000900087', 'Multiplique à direita', '$A=PDP^{-1}$.', 3), ('70000000-0000-4000-8000-000009000874', '40000000-0000-4000-8000-000000900087', 'Conclua', 'A ordem das colunas determina a ordem diagonal.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900088', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090005', 'multiple_choice', 'hard', 'published', 'Uma matriz $A$ satisfaz $Au=2u$ e $Av=3v$, com $(u,v)$ base. Se $x=u-2v$, qual é $A^4x$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000881', '40000000-0000-4000-8000-000000900088', 'A', '$8u-54v$', 1), ('50000000-0000-4000-8000-000009000882', '40000000-0000-4000-8000-000000900088', 'B', '$16u-81v$', 2), ('50000000-0000-4000-8000-000009000883', '40000000-0000-4000-8000-000000900088', 'C', '$32u-162v$', 3), ('50000000-0000-4000-8000-000009000884', '40000000-0000-4000-8000-000000900088', 'D', '$16u-162v$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900088', '50000000-0000-4000-8000-000009000884') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900088', '30000000-0000-4000-8000-000000090018', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000881', '40000000-0000-4000-8000-000000900088', 'Identifique a propriedade estrutural relevante antes de calcular.', 1), ('60000000-0000-4000-8000-000009000882', '40000000-0000-4000-8000-000000900088', 'Faça o cálculo simbólico de forma organizada.', 2), ('60000000-0000-4000-8000-000009000883', '40000000-0000-4000-8000-000000900088', 'Confira o resultado por traço, determinante, dimensão ou substituição.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900088', '$16u-162v$', 'Potências preservam cada direção própria e elevam o autovalor à potência correspondente. O coeficiente menos dois de $v$ permanece multiplicando $3^4$. $A^4x=16u-162v$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000881', '40000000-0000-4000-8000-000000900088', 'Eleve na primeira direção', '$A^4u=2^4u=16u$.', 1), ('70000000-0000-4000-8000-000009000882', '40000000-0000-4000-8000-000000900088', 'Eleve na segunda', '$A^4v=3^4v=81v$.', 2), ('70000000-0000-4000-8000-000009000883', '40000000-0000-4000-8000-000000900088', 'Use linearidade', '$A^4(u-2v)=16u-2(81v)$.', 3), ('70000000-0000-4000-8000-000009000884', '40000000-0000-4000-8000-000000900088', 'Conclua', '$A^4x=16u-162v$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900089', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090005', 'multiple_choice', 'hard', 'published', 'Uma matriz diagonalizável possui apenas autovalores $1$ e $4$. Qual polinômio em $A$ projeta sobre o autoespaço de $4$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000891', '40000000-0000-4000-8000-000000900089', 'A', '$(A-I)/3$', 1), ('50000000-0000-4000-8000-000009000892', '40000000-0000-4000-8000-000000900089', 'B', '$(4I-A)/3$', 2), ('50000000-0000-4000-8000-000009000893', '40000000-0000-4000-8000-000000900089', 'C', '$A-I$', 3), ('50000000-0000-4000-8000-000009000894', '40000000-0000-4000-8000-000000900089', 'D', '$A/4$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900089', '50000000-0000-4000-8000-000009000891') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900089', '30000000-0000-4000-8000-000000090018', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000891', '40000000-0000-4000-8000-000000900089', 'Identifique a propriedade estrutural relevante antes de calcular.', 1), ('60000000-0000-4000-8000-000009000892', '40000000-0000-4000-8000-000000900089', 'Faça o cálculo simbólico de forma organizada.', 2), ('60000000-0000-4000-8000-000009000893', '40000000-0000-4000-8000-000000900089', 'Confira o resultado por traço, determinante, dimensão ou substituição.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900089', '$(A-I)/3$', 'O polinômio projetor deve valer zero no autovalor um e um no autovalor quatro. A interpolação linear $(t-1)/3$ tem exatamente esses valores. Ele anula o primeiro autoespaço e fixa o segundo.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000891', '40000000-0000-4000-8000-000000900089', 'Defina a exigência', '$p(1)=0$ e $p(4)=1$.', 1), ('70000000-0000-4000-8000-000009000892', '40000000-0000-4000-8000-000000900089', 'Escolha o polinômio', '$p(t)=(t-1)/3$.', 2), ('70000000-0000-4000-8000-000009000893', '40000000-0000-4000-8000-000000900089', 'Substitua a matriz', '$p(A)=(A-I)/3$.', 3), ('70000000-0000-4000-8000-000009000894', '40000000-0000-4000-8000-000000900089', 'Confira', 'Ele anula o primeiro autoespaço e fixa o segundo.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900090', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090005', 'multiple_choice', 'hard', 'published', 'Uma transformação em $\mathbb R^3$ duplica volumes e inverte orientação. Qual pode ser seu determinante?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000901', '40000000-0000-4000-8000-000000900090', 'A', '$0$', 1), ('50000000-0000-4000-8000-000009000902', '40000000-0000-4000-8000-000000900090', 'B', '$-2$', 2), ('50000000-0000-4000-8000-000009000903', '40000000-0000-4000-8000-000000900090', 'C', '$2$', 3), ('50000000-0000-4000-8000-000009000904', '40000000-0000-4000-8000-000000900090', 'D', '$-8$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900090', '50000000-0000-4000-8000-000009000902') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900090', '30000000-0000-4000-8000-000000000008', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000901', '40000000-0000-4000-8000-000000900090', 'Identifique a propriedade estrutural relevante antes de calcular.', 1), ('60000000-0000-4000-8000-000009000902', '40000000-0000-4000-8000-000000900090', 'Faça o cálculo simbólico de forma organizada.', 2), ('60000000-0000-4000-8000-000009000903', '40000000-0000-4000-8000-000000900090', 'Confira o resultado por traço, determinante, dimensão ou substituição.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900090', '$-2$', 'O módulo do determinante fornece o fator de escala dos volumes, enquanto seu sinal registra a orientação. Duplicação com inversão corresponde a menos dois. O valor compatível é $-2$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000901', '40000000-0000-4000-8000-000000900090', 'Use o volume', '$|\det A|=2$.', 1), ('70000000-0000-4000-8000-000009000902', '40000000-0000-4000-8000-000000900090', 'Use a orientação', 'Inverter orientação exige determinante negativo.', 2), ('70000000-0000-4000-8000-000009000903', '40000000-0000-4000-8000-000000900090', 'Combine', '$\det A=-2$.', 3), ('70000000-0000-4000-8000-000009000904', '40000000-0000-4000-8000-000000900090', 'Conclua', 'O valor compatível é $-2$.', 4)
